class Solution {
public:
    int findPairs(vector<int>& nums, int k) {
        if (k < 0) return 0;
        unordered_map<int, int> count;
        for (int x : nums) count[x]++;
        int res = 0;
        for (const auto& [x, cnt] : count) {
            if (k == 0) {
                if (cnt >= 2) res++;
            } else {
                if (count.count(x + k)) res++;
            }
        }
        return res;
    }
};

class Solution {
    public int findPairs(int[] nums, int k) {
        if (k < 0) return 0;
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.put(x, count.getOrDefault(x, 0) + 1);
        int res = 0;
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            int x = entry.getKey(), cnt = entry.getValue();
            if (k == 0) {
                if (cnt >= 2) res++;
            } else {
                if (count.containsKey(x + k)) res++;
            }
        }
        return res;
    }
}

var findPairs = function(nums, k) {
    if (k < 0) return 0;
    const count = new Map();
    for (const x of nums) {
        count.set(x, (count.get(x) || 0) + 1);
    }
    let res = 0;
    for (const [x, cnt] of count.entries()) {
        if (k === 0) {
            if (cnt >= 2) res++;
        } else {
            if (count.has(x + k)) res++;
        }
    }
    return res;
};
